scripts.db:reset:local:
sh -aec 'set -a; . ./.env; set +a; db_pw="${POSTGRES_PASSWORD:-postgrespassword}"; db_url="postgresql://postgres@localhost:55432/postgres"; PGPASSWORD="$db_pw" psql -vON_ERROR_STOP=1 "$db_url" <<"SQL"
SELECT pg_terminate_backend(pid)
FROM pg_stat_activity
WHERE datname = current_database()
  AND pid <> pg_backend_pid();
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT ALL ON SCHEMA public TO postgres;
GRANT ALL ON SCHEMA public TO public;
SQL
for migration in $(find hasura/migrations/default -mindepth 2 -maxdepth 2 -name up.sql | sort); do PGPASSWORD="$db_pw" psql -vON_ERROR_STOP=1 -f "$migration" "$db_url"; done
pnpm hasura:metadata:apply
pnpm db:seed:local'
